#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor matmul_lt_impl_npu(const at::Tensor& A, const at::Tensor& B) {
    auto A_sizes = A.sizes();
    auto B_sizes = B.sizes();

    int64_t m = A_sizes[A.dim() - 2];
    int64_t n = B_sizes[B.dim() - 1];

    std::vector<int64_t> output_shape;
    for (int i = 0; i < A.dim() - 2; ++i) {
        output_shape.push_back(std::max(A_sizes[i], B_sizes[i]));
    }
    output_shape.push_back(m);
    output_shape.push_back(n);

    at::Tensor result = at::empty(output_shape, A.options());
    EXEC_NPU_CMD(aclnnMatmulForLowerTriangularMatricesCustom, A, B, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("matmul_for_lower_triangular_matrices_custom", &matmul_lt_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_for_lower_triangular_matrices_custom", &matmul_lt_impl_npu, "matmul for lower triangular matrices");
